# switchplayer.py: "Switch player" always one tap away (activities + Play Zone), clearer menu item, games opened from the activities page return there.
import base64, hashlib, os, sys
FULL = {'app/src/screens/CategoryScreen.tsx': ('', '615b9b88f50aa588589b869fe7e877d7'), 'app/src/screens/PlayZoneScreen.tsx': ('', 'c9345f8e91c208c811f4996f8fb49dea'), 'app/App.tsx': ('', 'b4dd9fddbdad41f4b40e6144f77aa94e'), 'app/src/components/AppMenu.tsx': ('', '9efd39a572805244480933a08752283b'), 'app/src/components/PlayerBar.tsx': ('', None), 'app/e2e/flows.spec.ts': ('', '8c2eff1a6c1840740e89a72d4a22edd2')}
for p, (b, orig) in FULL.items():
    if orig is None:
        if os.path.exists(p): sys.exit(p + ' already exists; not applying')
    elif hashlib.md5(open(p, 'rb').read()).hexdigest() != orig:
        sys.exit(p + ' changed since staging; not applying')
for p, (b, _) in FULL.items():
    open(p, 'wb').write(base64.b64decode(b)); print('wrote', p)
